contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount, uint seed) public payable {
        require(seed < 1 ether);
        require(address(this).balance >= seed + amount);
        // Fund c with `seed` wei via its payable fallback.
        (bool ok, ) = address(c).call{value: seed}("");
        require(ok);
        uint preSelf = address(this).balance;
        bool reverted;
        try c.go{value: amount}() { reverted = false; } catch { reverted = true; }
        if (reverted) {
            // Value refunded; c keeps its seed and pays nothing out.
            assert(address(this).balance + seed == preSelf);
        } else {
            // go() forwards msg.value to the target and sweeps c's whole balance
            // (at least `seed`) to the owner (this contract).
            assert(address(this).balance >= preSelf);
        }
    }
    receive() external payable {}
}

